using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct ShipmentId : IEquatable<ShipmentId>, IComparable<ShipmentId>
    {
        public Guid Value { get; }

        public ShipmentId(Guid value)
        {
            Value = value;
        }

        public static ShipmentId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static ShipmentId NewRandom() => new ShipmentId(Guid.NewGuid());

        public static ShipmentId Parse(string text) => new ShipmentId(Guid.Parse(text));

        public static bool TryParse(string text, out ShipmentId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new ShipmentId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(ShipmentId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is ShipmentId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(ShipmentId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(ShipmentId left, ShipmentId right) => left.Equals(right);

        public static bool operator !=(ShipmentId left, ShipmentId right) => !left.Equals(right);
    }
}
